D['date.checkin']=t=>col(`<div class="uip-box" style="display:flex;overflow:hidden;padding:0"><div style="flex:1;padding:6px 8px;background:var(--uip-acbg)"><div style="font-size:10px;color:${A}">${t('체크인','Check-in')}</div><b style="font-size:12px;font-weight:500">${t('11.14 (금)','Fri 11/14')}</b></div><div style="flex:1;padding:6px 8px"><div style="font-size:10px;color:${SUB}">${t('체크아웃','Check-out')}</div><b style="font-size:12px;font-weight:500">${t('11.17 (월)','Mon 11/17')}</b></div></div><div style="text-align:center">${tag(t('3박','3 nights'))}</div>`,'88%');
