D['text.counter']=t=>col(`<input maxlength="20" value="${t('오늘 거래','Deal today')}" style="width:100%;font-size:13px" oninput="this.nextElementSibling.textContent=this.value.length+'/20'"><div style="font-size:11px;color:${M};text-align:right">${t('5/20','10/20')}</div>`,'76%',3);
D['text.tag']=t=>`<div class="uip-field" style="width:82%;height:auto;min-height:34px;flex-wrap:wrap;gap:4px;padding:4px 6px">${['#AI','#UX'].map(x=>`<span class="uip-chip" style="padding:2px 8px">${x} ✕</span>`).join('')}<input placeholder="${t('태그 입력 후 Enter','Type, then Enter')}" style="border:0;outline:0;flex:1;min-width:60px;font-size:12px;background:none" onkeydown="if(event.key==='Enter'&&this.value){this.insertAdjacentHTML('beforebegin','<span class=&quot;uip-chip&quot; style=&quot;padding:2px 8px&quot;>#'+this.value+' ✕</span>');this.value=''}"></div>`;
