D['text.rich']=t=>`<div class="uip-box" style="width:84%;padding:0"><div style="display:flex;gap:10px;padding:5px 8px;border-bottom:0.5px solid ${B};font-size:12px"><b>B</b><i>I</i><u>U</u><span>•</span><span>🔗</span></div><div contenteditable style="padding:6px 8px;font-size:12px;outline:0;min-height:40px">${t('여기에 <b>굵게</b> 써보세요','Try <b>bold</b> here')}</div></div>`;
