D['search.auto']=t=>col(sbar(t('니트','knit')+'<span class="uip-caret"></span>')+box([t('가디건','cardigan'),t('원피스','dress'),t('조끼','vest')].map(x=>`<div style="padding:3px 0"><b style="color:${A};font-weight:500">${t('니트','knit')}</b> ${x}</div>`).join(''),'font-size:12px;padding:4px 10px'),'82%',4);
D['search.recent']=t=>col(sbar('')+`<div style="font-size:11px;color:${SUB}">${t('최근 검색어','Recent')}</div><div style="display:flex;gap:5px;flex-wrap:wrap">${[t('제주 숙소','Jeju stay'),t('가습기','Humidifier')].map(x=>`<span class="uip-chip" onclick="this.remove()">${x} ✕</span>`).join('')}</div>`,'82%',5);
