D['search.highlight']=t=>col(sbar(t('오사카','Osaka'))+box([t('3박 4일 패키지','3-night package'),t('맛집 지도','food map')].map(x=>`<div style="padding:2px 0"><b style="color:${A};font-weight:500">${t('오사카','Osaka')}</b> ${x}</div>`).join(''),'font-size:12px;padding:4px 10px'),'82%',4);
