D['primary.hamburger']=t=>top(`<span style="cursor:pointer;font-size:16px" onclick="const d=this.closest('.uip-pv').querySelector('.uip-drawer');d.style.transform=d.style.transform?'':'translateX(-100%)'">≡</span><b style="font-weight:500">${t('쇼핑','Shop')}</b>`)+`<div class="uip-drawer" style="top:30px;transform:translateX(-100%);transition:.3s;border-right:0.5px solid ${B};line-height:2">${[t('홈','Home'),t('카테고리','Categories'),t('찜','Saved')].join('<br>')}</div><div style="margin-top:20px;width:80%">${rows(2)}</div>`+cap(t('≡ 를 눌러보세요','Tap ≡'));
