D['primary.mega']=t=>`<div style="position:absolute;top:0;left:0;right:0;height:28px;background:${S};border-bottom:0.5px solid ${B};display:flex;align-items:center;padding:0 10px;gap:12px;font-size:11px"><span style="color:${A}">${t('제품 ▴','Products ▴')}</span><span>${t('가격','Pricing')}</span></div><div style="position:absolute;top:28px;left:6px;right:6px;background:${S};border:0.5px solid ${B};border-radius:0 0 10px 10px;padding:8px;display:grid;grid-template-columns:repeat(3,1fr);gap:6px;font-size:10px">${[[t('분석','Analytics'),t('리포트','Reports')],[t('자동화','Automation'),t('연동','Integrations')],[t('보안','Security'),t('관리','Admin')]].map(c=>`<div><b style="font-weight:500">${c[0]}</b><div style="color:${SUB}">${c[1]}</div></div>`).join('')}</div>`;
D['primary.rail']=t=>`<div style="position:absolute;left:0;top:0;bottom:0;width:44px;background:${S};border-right:0.5px solid ${B};display:flex;flex-direction:column;align-items:center;gap:10px;padding-top:10px;font-size:15px">${['⌂','✉','☰','⚙'].map((x,i)=>`<span style="width:30px;height:24px;border-radius:12px;display:flex;align-items:center;justify-content:center;cursor:pointer;${i==0?'background:var(--uip-acbg);color:'+A:''}" onclick="[...this.parentNode.children].forEach(c=>{c.style.background='';c.style.color=''});this.style.background='var(--uip-acbg)';this.style.color='${A}'">${x}</span>`).join('')}</div><div style="margin-left:44px;width:60%">${rows(3)}</div>`;
D['primary.command']=t=>dim+`<div class="uip-box" style="position:relative;width:82%;padding:0;font-size:12px"><div style="padding:7px 10px;border-bottom:0.5px solid ${B}">⌕ ${t('새','new')}<span class="uip-caret"></span><span style="float:right;color:${M};font-size:10px">⌘K</span></div><div style="padding:4px 0">${[t('새 문서','New doc'),t('새 프로젝트','New project'),t('새 팀원 초대','Invite teammate')].map((x,i)=>`<div style="padding:4px 10px;${i==0?'background:var(--uip-acbg);color:'+A:''}">${x}</div>`).join('')}</div></div>`;
D['primary.floating']=t=>`<div style="margin-bottom:24px;width:80%">${rows(2)}</div><div style="position:absolute;bottom:10px;left:50%;transform:translateX(-50%);background:#14171f;border-radius:20px;padding:6px 14px;display:flex;gap:16px;font-size:14px;color:#9aa0aa">${['⌂','⌕','♡','☺'].map((x,i)=>`<span style="cursor:pointer;${i==0?'color:#fff':''}" onclick="[...this.parentNode.children].forEach(c=>c.style.color='');this.style.color='#fff'">${x}</span>`).join('')}</div>`;
/* tabs */
const tabs=(arr,on=0,ex='')=>`<div style="display:flex;gap:14px;font-size:12px;border-bottom:0.5px solid ${B};${ex}">${arr.map((x,i)=>`<span style="padding:5px 0;cursor:pointer;${i===on?'border-bottom:2px solid '+A+';color:'+A:'color:'+SUB}" onclick="[...this.parentNode.children].forEach(c=>{c.style.borderBottom='';c.style.color='${SUB}'});this.style.borderBottom='2px solid ${A}';this.style.color='${A}'">${x}</span>`).join('')}</div>`;
D['tabs.tabs']=t=>col(tabs([t('상품정보','Details'),t('리뷰','Reviews'),t('문의','Q&A')])+rows(2),'84%');
D['tabs.segmented']=t=>`<div class="uip-seg">${[t('지도','Map'),t('목록','List')].map((x,i)=>`<span class="${i?'':'on'}" onclick="UIP.fx.seg(this)" style="padding:6px 22px">${x}</span>`).join('')}</div>`;
D['tabs.scroll']=t=>`<div style="width:86%;overflow-x:auto;white-space:nowrap">${tabs([t('전체','All'),t('패션','Fashion'),t('뷰티','Beauty'),t('가전','Electronics'),t('식품','Food'),t('스포츠','Sports')],0,'width:max-content')}</div>`+cap(t('옆으로 밀어 보세요','Scroll sideways'));
D['tabs.chip']=t=>`<div style="display:flex;gap:5px;flex-wrap:wrap;width:86%">${chips([t('전체','All'),t('진행 중','Active'),t('완료','Done'),t('보관','Archived')],0)}</div>`;
D['tabs.sticky']=t=>`<div style="position:absolute;inset:0;overflow-y:auto"><div style="height:44px;background:linear-gradient(135deg,#9db8ff,#c7a8ff)"></div><div style="position:sticky;top:0;background:${S};padding:0 10px">${tabs([t('메뉴','Menu'),t('리뷰','Reviews'),t('정보','Info')])}</div><div style="padding:6px 12px">${rows(6)}</div></div>`+cap(t('아래로 스크롤','Scroll down'));
D['tabs.vertical']=t=>`<div class="uip-box" style="display:flex;width:86%;padding:0;font-size:11px;height:84px"><div style="width:38%;border-right:0.5px solid ${B};padding:4px 0">${[t('계정','Account'),t('알림','Alerts'),t('결제','Billing')].map((x,i)=>`<div class="uip-sel${i?'':' on'}" style="padding:5px 8px;cursor:pointer" onclick="UIP.fx.pick(this)">${x}</div>`).join('')}</div><div style="flex:1;padding:8px">${ln('80%')}<div style="height:6px"></div>${ln('60%')}</div></div>`;
D['tabs.icon']=t=>`<div style="display:flex;gap:4px;width:80%;border-bottom:0.5px solid ${B};font-size:16px">${['▦','▶','☺'].map((x,i)=>`<span style="flex:1;text-align:center;padding:5px 0;cursor:pointer;${i==0?'border-bottom:2px solid '+A:'color:'+M}" onclick="[...this.parentNode.children].forEach(c=>{c.style.borderBottom='';c.style.color='${M}'});this.style.borderBottom='2px solid ${A}';this.style.color=''">${x}</span>`).join('')}</div>`;
/* wayfinding */
D['wayfinding.back']=t=>top(`<span style="font-size:16px;color:${A}">‹</span><span style="color:${A}">${t('목록','List')}</span>`)+`<div style="margin-top:20px;width:80%">${rows(2)}</div>`;
D['wayfinding.infinite']=t=>`<div style="position:absolute;inset:8px 12px;overflow:hidden"><div style="animation:uip-scrollup 4s linear infinite">${rows(8)}<div style="text-align:center;padding:6px">${sp(14)}</div></div></div><style>@keyframes uip-scrollup{to{transform:translateY(-120px)}}</style>`;
D['wayfinding.more']=t=>col(rows(3)+btn2(t('더보기 (12)','Load more (12)'),'padding:5px;font-size:12px'),'82%',4);
D['wayfinding.pagination']=t=>`<div style="display:flex;gap:4px;font-size:12px;align-items:center"><span style="padding:0 6px">‹</span>${[1,2,3,4,5].map(n=>`<span class="uip-chip${n==1?' on':''}" onclick="UIP.fx.pick(this)" style="width:26px;text-align:center;padding:3px 0;border-radius:6px">${n}</span>`).join('')}<span style="padding:0 6px">›</span></div>`;
D['wayfinding.breadcrumb']=t=>`<div style="font-size:12px;color:${SUB}">${t('홈','Home')} › ${t('가전','Electronics')} › <b style="color:var(--uip-tx);font-weight:500">${t('노트북','Laptops')}</b></div>`;
