D['wayfinding.top']=t=>`<div style="width:80%">${rows(3)}</div><button class="uip-ibtn" style="position:absolute;right:12px;bottom:12px;border-radius:50%;width:34px;height:34px">↑</button>`;
D['wayfinding.toc']=t=>box(`<div style="font-size:11px;line-height:1.9"><b style="font-weight:500">${t('목차','Contents')}</b>${[t('1. 시작하기','1. Getting started'),t('2. 설치','2. Install'),t('3. 설정','3. Configure')].map((x,i)=>`<div style="padding-left:6px;${i==1?'color:'+A+';border-left:2px solid '+A:'border-left:2px solid transparent'}">${x}</div>`).join('')}</div>`,'width:72%');
D['wayfinding.prevnext']=t=>`<div style="display:flex;gap:8px;width:88%">${[[t('‹ 이전 글','‹ Previous'),t('설치 가이드','Install guide')],[t('다음 글 ›','Next ›'),t('설정하기','Configuration')]].map((r,i)=>box(`<div style="font-size:10px;color:${SUB}">${r[0]}</div><div style="font-size:12px">${r[1]}</div>`,'flex:1;'+(i?'text-align:right':''))).join('')}</div>`;
/* list */
const thumb=(c,s=20)=>`<span style="width:${s}px;height:${s}px;border-radius:5px;flex:none;background:${c}"></span>`;
