D['list.carousel']=t=>`<div style="display:flex;gap:8px;animation:uip-car 4s infinite;padding-left:24%">${[0,1,2].map(i=>`<div style="width:90px;height:70px;flex:none;border-radius:12px;background:${i==1?A:BS}"></div>`).join('')}</div><div style="position:absolute;bottom:8px;display:flex;gap:4px">${[1,0,0].map(o=>`<span style="width:${o?14:5}px;height:5px;border-radius:3px;background:${o?A:BS}"></span>`).join('')}</div><style>@keyframes uip-car{0%,40%{transform:none}50%,90%{transform:translateX(-98px)}}</style>`;
