D['list.swipe']=t=>`<div style="position:relative;width:84%;height:40px;border-radius:10px;overflow:hidden;background:${DG}"><span style="position:absolute;right:14px;top:12px;font-size:12px;color:#fff">${t('삭제','Delete')}</span><div onclick="this.style.transform=this.style.transform?'':'translateX(-64px)'" style="position:absolute;inset:0;background:${S};border:0.5px solid ${B};border-radius:10px;display:flex;align-items:center;padding:0 10px;font-size:12px;cursor:pointer;transition:transform .3s">${t('장보기 목록 ‹','Groceries ‹')}</div></div>`+cap(t('눌러서 밀기','Tap to swipe'));
