D['scroll.sticky']=t=>scr(`<div style="position:sticky;top:0;background:${S};border-bottom:0.5px solid ${B};padding:5px 8px;font-size:11px;z-index:1"><b style="font-weight:500">${t('오늘의 특가','Today’s deals')}</b> <span style="color:${A}">12:30:15</span></div><div style="padding:4px 8px">${rows(8)}</div>`)+cap(t('스크롤해 보세요','Scroll it'));
D['scroll.horizontal']=t=>`<div style="width:90%;overflow-x:auto;display:flex;gap:6px;padding-bottom:4px">${Array.from({length:6},(_,i)=>`<div style="flex:none;width:64px;height:64px;border-radius:10px;background:${i==1?A:BS}"></div>`).join('')}</div>`+cap(t('옆으로 밀어 보세요','Scroll sideways'));
D['scroll.parallax']=t=>`<div style="position:absolute;inset:6px 10px;overflow-y:auto;border-radius:6px" onscroll="this.querySelector('.bg').style.transform='translateY('+this.scrollTop*0.5+'px)'"><div style="position:relative;height:60px;overflow:hidden"><div class="bg" style="position:absolute;inset:-20px 0 0;background:linear-gradient(#9db8ff,#c7a8ff)"><span style="position:absolute;right:16px;top:26px;width:18px;height:18px;border-radius:50%;background:#ffd166"></span></div></div><div style="background:${S};padding:6px 8px">${rows(6)}</div></div>`+cap(t('스크롤하면 배경이 느리게','Background moves slower'));
