D['scroll.story']=t=>`<div style="position:absolute;inset:6px 10px;overflow-y:auto;border-radius:6px;background:${S}" onscroll="const k=Math.min(1,this.scrollTop/120);this.querySelector('.bar').style.height=(20+k*50)+'px';this.querySelector('.num').textContent=Math.round(20+k*80)+'%'"><div style="position:sticky;top:0;height:90px;display:flex;align-items:flex-end;gap:10px;padding:8px;background:${S}"><div class="bar" style="width:24px;height:20px;background:${A};border-radius:3px"></div><b class="num" style="font-size:16px;font-weight:500">20%</b></div><div style="height:160px"></div></div>`+cap(t('스크롤하면 이야기가 진행','Scroll moves the story'));
/* micro-interactions */
D['micro.like']=t=>`<span style="font-size:34px;cursor:pointer;color:${M};display:inline-block" onclick="const on=this.textContent==='♡';this.textContent=on?'♥':'♡';this.style.color=on?'${DG}':'${M}';if(on)this.animate([{transform:'scale(1)'},{transform:'scale(1.45)'},{transform:'scale(.9)'},{transform:'scale(1)'}],{duration:450})">♡</span>`+cap(t('눌러보세요','Tap it'));
D['micro.press']=t=>`<button class="uip-btn" style="transition:transform .1s" onpointerdown="this.style.transform='scale(.92)'" onpointerup="this.style.transform=''" onpointerleave="this.style.transform=''">${t('결제하기','Pay now')}</button>`+cap(t('꾹 눌러보세요','Press and hold'));
