D['micro.confetti']=t=>D['completion.confetti'](t);
D['micro.haptic']=t=>`<div style="width:44px;height:70px;border-radius:10px;border:2px solid currentColor;display:flex;align-items:center;justify-content:center;font-size:10px;cursor:pointer" onclick="this.animate([{transform:'translateX(0)'},{transform:'translateX(-2px) rotate(-2deg)'},{transform:'translateX(2px) rotate(2deg)'},{transform:'translateX(0)'}],{duration:220});try{navigator.vibrate&&navigator.vibrate(20)}catch(e){}">${t('탭','Tap')}</div>`+cap(t('실제로는 짧은 진동','A short buzz on a real device'));
D['micro.hover']=t=>`<div onmouseenter="this.style.transform='translateY(-6px)'" onmouseleave="this.style.transform=''" class="uip-box" style="width:62%;padding:12px;transition:transform .2s;cursor:pointer">${ln('55%','currentColor')}<div style="height:6px"></div>${ln()}</div>`+cap(t('마우스를 올려보세요','Hover it'));
/* transitions: two screens, auto-play */
const tr=(anim,ex='')=>`<div style="position:relative;width:96px;height:110px;border-radius:12px;border:1.5px solid ${BS};overflow:hidden;background:${S}"><div style="padding:8px">${ln('70%')}<div style="height:5px"></div>${ln('50%')}</div><div style="position:absolute;inset:0;background:var(--uip-acbg);padding:8px;animation:${anim} 3s ease-in-out infinite;${ex}"><div style="height:30px;border-radius:5px;background:${A};opacity:.7"></div><div style="height:5px"></div>${ln('60%')}</div></div>`;
const kf=`<style>@keyframes uip-tpush{0%,20%{transform:translateX(100%)}40%,80%{transform:none}100%{transform:translateX(100%)}}@keyframes uip-tmodal{0%,20%{transform:translateY(100%)}40%,80%{transform:none}100%{transform:translateY(100%)}}@keyframes uip-tfade{0%,20%{opacity:0}40%,80%{opacity:1}100%{opacity:0}}@keyframes uip-tft{0%,20%{opacity:0;transform:scale(.92)}40%,80%{opacity:1;transform:none}100%{opacity:0}}@keyframes uip-tzoom{0%,20%{transform:scale(.2);opacity:0}40%,80%{transform:none;opacity:1}100%{transform:scale(.2);opacity:0}}@keyframes uip-tcard{0%,20%{clip-path:inset(40% 20% 30% 20% round 8px)}40%,80%{clip-path:inset(0 0 0 0 round 0)}100%{clip-path:inset(40% 20% 30% 20% round 8px)}}@keyframes uip-tsheet{0%,20%{transform:translateY(60%)}40%,80%{transform:none}100%{transform:translateY(60%)}}@keyframes uip-tmorph{0%,20%{clip-path:circle(10% at 80% 85%)}40%,80%{clip-path:circle(150% at 80% 85%)}100%{clip-path:circle(10% at 80% 85%)}}@keyframes uip-tcurl{0%,20%{transform:perspective(300px) rotateY(-90deg);transform-origin:left}40%,80%{transform:perspective(300px) rotateY(0);transform-origin:left}100%{transform:perspective(300px) rotateY(-90deg);transform-origin:left}}</style>`;
D['transition.push']=t=>tr('uip-tpush')+kf;
D['transition.modal']=t=>tr('uip-tmodal')+kf;
D['transition.tab']=t=>`<div style="position:relative;width:96px;height:110px;border-radius:12px;border:1.5px solid ${BS};overflow:hidden;background:${S}"><div style="display:flex;width:200%;animation:uip-tab 4s ease-in-out infinite">${[A,'#f5a524'].map(c=>`<div style="width:50%;padding:8px;display:grid;grid-template-columns:1fr 1fr;gap:4px">${[0,1,2,3].map(()=>`<div style="height:24px;border-radius:4px;background:${c};opacity:.5"></div>`).join('')}</div>`).join('')}</div><div style="position:absolute;bottom:4px;left:0;right:0;display:flex;justify-content:center;gap:4px"><span style="width:5px;height:5px;border-radius:50%;background:${A}"></span><span style="width:5px;height:5px;border-radius:50%;background:${BS}"></span></div></div><style>@keyframes uip-tab{0%,35%{transform:none}50%,85%{transform:translateX(-50%)}100%{transform:none}}</style>`;
D['transition.fadethrough']=t=>tr('uip-tft')+kf;
D['transition.sheet']=t=>tr('uip-tsheet','top:30%;border-radius:12px 12px 0 0')+kf;
D['transition.card']=t=>tr('uip-tcard')+kf;
D['transition.shared']=t=>`<div style="position:relative;width:96px;height:110px;border-radius:12px;border:1.5px solid ${BS};overflow:hidden;background:${S}"><div style="position:absolute;background:${A};opacity:.75;animation:uip-shared 3s ease-in-out infinite"></div></div><style>@keyframes uip-shared{0%,20%{left:8px;top:8px;width:28px;height:28px;border-radius:6px}40%,80%{left:0;top:0;width:96px;height:56px;border-radius:0}100%{left:8px;top:8px;width:28px;height:28px;border-radius:6px}}</style>`+cap(t('같은 그림이 이어지며 커짐','Same image carries over'));
D['transition.zoom']=t=>tr('uip-tzoom')+kf;
D['transition.stagger']=t=>`<div style="width:96px;height:110px;border-radius:12px;border:1.5px solid ${BS};background:${S};padding:8px;display:flex;flex-direction:column;gap:6px">${[0,1,2,3].map(i=>`<div style="height:18px;border-radius:5px;background:${i?BS:A};animation:uip-fadeup 2.6s infinite ${i*.15}s"></div>`).join('')}</div>`;
D['transition.crossfade']=t=>`<div style="position:relative;width:96px;height:110px;border-radius:12px;overflow:hidden"><div style="position:absolute;inset:0;background:linear-gradient(135deg,#9db8ff,#c7a8ff)"></div><div style="position:absolute;inset:0;background:linear-gradient(135deg,#ffd6a5,#ff9f9f);animation:uip-tfade 3s ease-in-out infinite"></div></div>`+kf;
D['transition.morph']=t=>tr('uip-tmorph')+kf;
D['transition.curl']=t=>tr('uip-tcurl')+kf;
/* AI states */
D['aistate.thinking']=t=>rowf(`<span style="font-size:16px;color:${A};animation:uip-sp 2s linear infinite;display:inline-block">✳</span><span style="font-size:12px;background:linear-gradient(90deg,${M},var(--uip-tx),${M});background-size:200% 100%;-webkit-background-clip:text;color:transparent;animation:uip-sh 1.6s linear infinite">${t('생각하는 중…','Thinking…')}</span>`,8);
D['aistate.steps']=t=>col([[t('파일 읽기','Reading files'),2],[t('표 정리','Building table'),1],[t('요약 작성','Writing summary'),0]].map(r=>rowf(`<span style="width:14px;text-align:center">${r[1]==2?`<span style="color:${'var(--text-success,#2f9e44)'}">✓</span>`:r[1]==1?sp(12):`<span style="color:${M}">○</span>`}</span><span style="font-size:12px;${r[1]==0?'color:'+M:''}">${r[0]}</span>`,8)).join(''),'72%',6);
D['aistate.inline']=t=>box(`<div style="font-size:12px">${t('회의는 다음 주 화요일','The meeting is next Tuesday')}<span style="color:${M}">${t(' 오후 2시로 잡을게요','at 2 PM')}</span></div><div style="font-size:10px;color:${M};margin-top:4px">${t('Tab 키로 받아들이기','Press Tab to accept')}</div>`,'width:84%');
D['aistate.label']=t=>box(rowf(tag('✦ AI')+`<span style="font-size:11px;color:${SUB}">${t('AI가 만든 요약이에요','AI-generated summary')}</span>`)+`<div style="height:6px"></div>${ln('90%')}`,'width:84%');
D['aistate.diff']=t=>box(`<div style="font-size:11px;font-family:monospace;line-height:1.7"><div style="background:var(--bg-danger,#fdeaea);color:${DG}">- ${t('매출이 늘었다','Sales grew')}</div><div style="background:var(--bg-success,#e6f6ea);color:var(--text-success,#2f9e44)">+ ${t('매출이 12% 늘었다','Sales grew 12%')}</div></div>${rowf(btn2(t('거절','Reject'),'flex:1;padding:3px;font-size:11px')+btn(t('수락','Accept'),'flex:1;padding:3px;font-size:11px'),6,'margin-top:6px')}`,'width:86%');
D['aistate.copilot']=t=>`<div style="position:absolute;inset:0;display:flex"><div style="flex:1;padding:10px">${rows(4)}</div><div style="width:42%;background:${S};border-left:0.5px solid ${B};padding:6px;display:flex;flex-direction:column;gap:5px;font-size:10px"><b style="font-weight:500">✦ ${t('어시스턴트','Assistant')}</b><div style="background:var(--uip-acbg);color:${A};border-radius:6px;padding:4px">${t('이 문서 요약할까요?','Summarize this doc?')}</div><div style="flex:1"></div><div style="border:0.5px solid ${BS};border-radius:6px;padding:3px;color:${M}">${t('질문하기','Ask…')}</div></div></div>`;
D['aistate.sparkle']=t=>`<button class="uip-btn2" style="border-color:${A};color:${A}" onclick="this.animate([{transform:'scale(1)'},{transform:'scale(1.08)'},{transform:'scale(1)'}],{duration:300})">✦ ${t('AI로 다듬기','Improve with AI')}</button>`;
