D['inputpairs.clearshow']=t=>P(`<div class="uip-box" style="padding:4px 6px;font-size:10px;width:60px;display:flex">abc<span style="margin-left:auto;color:${M}">ⓧ</span></div>`,t('지우기','Clear'),`<div class="uip-box" style="padding:4px 6px;font-size:10px;width:60px;display:flex">●●●<span style="margin-left:auto">👁</span></div>`,t('보이기','Show'));
D['inputpairs.counter']=t=>P(`<div style="width:60px"><div class="uip-box" style="height:16px"></div><div style="font-size:8px;color:${M};text-align:right">5/50</div></div>`,t('몇 자 썼는지','How many typed'),`<div style="width:60px"><div class="uip-box" style="height:16px;border-color:${DG}"></div><div style="font-size:8px;color:${DG};text-align:right">${t('최대 8자','Max 8')}</div></div>`,t('더 못 씀','Can’t type more'));
D['inputpairs.numpad']=t=>P(`<div style="display:grid;grid-template-columns:repeat(3,12px);gap:2px">${[1,2,3,4,5,6,7,8,9].map(n=>`<span style="font-size:8px;text-align:center;border:0.5px solid ${BS};border-radius:2px">${n}</span>`).join('')}</div>`,t('숫자만','Numbers'),`<div style="display:grid;grid-template-columns:repeat(6,8px);gap:2px">${Array.from({length:18},()=>`<span style="height:8px;border:0.5px solid ${BS};border-radius:2px"></span>`).join('')}</div>`,t('글자 전체','Full keyboard'));
D['inputpairs.date']=t=>P(`<div class="uip-box" style="padding:4px 6px;font-size:10px">2026.11.</div>`,t('직접 입력','Type it'),`<div style="display:grid;grid-template-columns:repeat(4,9px);gap:2px">${Array.from({length:12},(_,i)=>`<span style="height:9px;border-radius:2px;background:${i==6?A:B}"></span>`).join('')}</div>`,t('달력에서 고름','Pick on a calendar'));
D['inputpairs.required']=t=>P(`<div style="font-size:10px">${t('이름','Name')} <span style="color:${DG}">*</span><div class="uip-box" style="height:14px;width:56px;border-color:${DG}"></div></div>`,t('꼭 채움','Must fill'),`<div style="font-size:10px">${t('메모','Note')} <span style="color:${M}">(${t('선택','opt.')})</span><div class="uip-box" style="height:14px;width:56px"></div></div>`,t('비워도 됨','Can skip'));
const I=(a,al,b,bl)=>P(`<span class="uip-ibtn" style="display:flex;align-items:center;justify-content:center;font-size:18px">${a}</span>`,al,`<span class="uip-ibtn" style="display:flex;align-items:center;justify-content:center;font-size:18px">${b}</span>`,bl);
D['icons.hamburger']=t=>I('≡',t('전체 메뉴','Main menu'),'⋮',t('이것의 더보기','More for this'));
D['icons.kebab']=t=>I('⋮',t('세로 (안드로이드)','Vertical (Android)'),'⋯',t('가로 (iOS·웹)','Horizontal (iOS, web)'));
D['icons.closeback']=t=>I('✕',t('창을 닫음','Close a window'),'‹',t('이전 화면','Previous screen'));
D['icons.heartbookmark']=t=>I('♡',t('좋아요 표시','Like'),'⌑',t('나중에 보기 저장','Save for later'));
D['icons.shareexport']=t=>I('⤴',t('남에게 보냄','Send to others'),'⇪',t('파일로 꺼냄','Save as a file'));
D['icons.filtersort']=t=>I('⏷',t('일부만 거름','Narrow down'),'⇅',t('순서만 바꿈','Change order'));
D['icons.searchzoom']=t=>I('⌕',t('찾기','Search'),'⊕',t('크게 보기','Zoom in'));
D['icons.refreshundo']=t=>I('↻',t('다시 불러옴','Reload'),'↶',t('방금 것 취소','Undo last'));
D['icons.editcompose']=t=>I('✎',t('있는 것 고침','Edit existing'),'✚',t('새로 씀','Write new'));
