const menuList=(n=4,act=1)=>Array.from({length:n},(_,i)=>`<div style="height:9px;border-radius:4px;margin:6px 6px;background:${i===act?A:BS};opacity:${i===act?1:.8}"></div>`).join('');
const page=`<div style="padding:8px">${ln('60%')}<div style="height:30px;border-radius:6px;background:${B};margin:6px 0"></div>${ln('80%')}<div style="height:5px"></div>${ln('50%')}</div>`;
