D['sidenav.twolevel']=t=>P(ab(['⌂','▤','✉','⚙'].map((x,i)=>`<div style="font-size:10px;margin:7px 0;text-align:center;color:${i==1?A:M}">${x}</div>`).join(''),`left:0;top:0;bottom:0;width:20px;border-right:0.5px solid ${B};padding-top:4px`)+ab(`<div style="font-size:8px;color:${M};margin:2px 4px">${t('프로젝트','PROJECTS')}</div>`+menuList(3,0),`left:20px;top:0;bottom:0;width:44px;background:${S};border-right:0.5px solid ${B};padding-top:6px`)+`<div style="margin-left:64px;padding:6px">${ln('80%')}</div>`);
