D['sidenav.drilldown']=t=>P(`<div style="display:flex;width:200%;height:100%;${an('u6drill',3.5)}"><div style="width:50%;padding:6px;font-size:10px">${[t('홈','Home'),t('프로젝트 ›','Projects ›'),t('설정','Settings')].map((x,i)=>`<div style="padding:5px 2px;color:${i==1?A:''}">${x}</div>`).join('')}</div><div style="width:50%;padding:6px;font-size:10px"><div style="color:${A};padding:3px 0">‹ ${t('프로젝트','Projects')}</div>${['웹','앱','아카이브'].map((x,i)=>`<div style="padding:4px 4px;color:${SUB}">· ${t(x,['Website','App','Archive'][i])}</div>`).join('')}</div></div>`);
