D['sidenav.stack3d']=t=>P(`<div style="position:absolute;inset:0;background:var(--uip-acbg);padding-top:8px">${menuList(5,1)}</div><div style="position:absolute;inset:0;background:${S};box-shadow:0 4px 14px rgba(0,0,0,.2);transform-origin:left center;${an('u6st3d')}">${bar+page}</div>`);
D['sidenav.enddrawer']=t=>P(bar+page+ab('',`inset:0;background:rgba(10,15,40,.3);${an('u6fd')}`)+ab(`<div style="text-align:center;padding-top:8px"><div style="width:20px;height:20px;border-radius:50%;background:${A};margin:0 auto 4px"></div>${menuList(3,-1)}</div>`,`right:0;top:0;bottom:0;width:62%;background:${S};z-index:2;${an('u6inr')}`));
D['sidenav.workspaces']=t=>P(ab(['A','B','+'].map((x,i)=>`<div style="width:16px;height:16px;border-radius:5px;margin:5px auto;font-size:8px;display:flex;align-items:center;justify-content:center;color:#fff;background:${i==0?A:i==1?'#a06cff':BS}">${x}</div>`).join(''),`left:0;top:0;bottom:0;width:24px;background:${B};padding-top:4px`)+ab(`<div style="font-size:8px;color:${M};margin:2px 4px"># ${t('채널','channels')}</div>`+['general','design','launch'].map((x,i)=>`<div style="font-size:9px;margin:4px 5px;color:${i==1?A:SUB}"># ${x}</div>`).join(''),`left:24px;top:0;bottom:0;width:46px;padding-top:6px;border-right:0.5px solid ${B}`));
D['sidenav.search']=t=>P(`<div style="padding:6px"><div style="border:0.5px solid ${BS};border-radius:6px;font-size:9px;padding:3px 5px;color:${SUB}">⌕ pro<span style="animation:uip-cur 1s steps(1) infinite">|</span></div>${[t('▤ 프로젝트','▤ Projects'),t('◯ 프로필','◯ Profile')].map((x,i)=>`<div style="font-size:9px;padding:5px 3px;margin-top:3px;border-radius:5px;${i==0?'background:var(--uip-acbg);color:'+A:'color:'+SUB}">${x}</div>`).join('')}</div>`);
D['sidenav.liquidrail']=t=>P(ab(`<div style="position:relative">${['⌂','▤','✉','◯'].map((x,i)=>`<div style="font-size:10px;height:20px;line-height:20px;text-align:center;color:${M}">${x}</div>`).join('')}<div style="position:absolute;left:2px;right:2px;height:20px;border-radius:10px;background:rgba(255,255,255,.35);border:1px solid rgba(255,255,255,.7);backdrop-filter:blur(4px);animation:u6ind 4s cubic-bezier(.6,-0.3,.4,1.3) infinite;top:0" class="u6v"></div></div>`,`left:5px;top:12px;bottom:12px;width:22px;border-radius:12px;background:linear-gradient(${A},#a06cff);padding:4px 0`)+`<div style="margin-left:30px">${page}</div>`);

