const icons4=(act=-1)=>`<div style="display:flex;justify-content:space-around;align-items:center;height:100%;font-size:11px">${['⌂','⌕','♡','◯'].map((x,i)=>`<span style="color:${i===act?A:M}">${x}</span>`).join('')}</div>`;
D['bottomnav.sliding']=t=>P(page+bnav(icons4()+`<div style="position:absolute;top:0;width:17%;height:2.5px;border-radius:2px;background:${A};${an('u6ind',4)}"></div>`));
D['bottomnav.expanding']=t=>P(page+bnav(`<div style="display:flex;justify-content:space-around;align-items:center;height:100%;font-size:10px"><span style="color:${M}">⌂</span><span style="color:${M}">⌕</span><span style="background:var(--uip-acbg);color:${A};border-radius:10px;padding:2px 7px;white-space:nowrap;overflow:hidden;display:inline-block;${an('u6w',3)}">♡ ${t('찜','Likes')}</span><span style="color:${M}">◯</span></div>`));
D['bottomnav.center']=t=>P(page+bnav(icons4())+ab('+',`left:50%;bottom:12px;transform:translateX(-50%);width:24px;height:24px;border-radius:50%;background:${A};color:#fff;font-size:15px;line-height:22px;text-align:center;box-shadow:0 3px 8px rgba(0,0,0,.2)`)+[[-26,-26],[0,-36],[26,-26]].map(([x,y],i)=>ab(['▣','✎','◷'][i],`left:calc(50% + ${x}px - 8px);bottom:${-y+8}px;width:16px;height:16px;border-radius:50%;background:${S};border:0.5px solid ${BS};font-size:8px;text-align:center;line-height:16px;${an('u6dial',3)};animation-delay:${i*.08}s`)).join(''));
D['bottomnav.floating']=t=>P(page+ab(icons4(2),`left:8px;right:8px;bottom:6px;height:22px;border-radius:12px;background:${S};border:0.5px solid ${BS};box-shadow:0 4px 12px rgba(0,0,0,.15)`));
D['bottomnav.hide']=t=>P(`<div style="${an('u6scr',4)}">${page}${page}</div>`+bnav(icons4(0),an('u6hide',4)));
D['bottomnav.badges']=t=>P(page+bnav(`<div style="display:flex;justify-content:space-around;align-items:center;height:100%;font-size:11px;color:${M}">${['⌂','✉','🔔','◯'].map((x,i)=>`<span style="position:relative">${x}${i==1?`<b style="position:absolute;top:-4px;right:-7px;font-size:7px;background:var(--uip-danger);color:#fff;border-radius:6px;padding:0 3px">3</b>`:''}${i==2?`<b style="position:absolute;top:-1px;right:-3px;width:5px;height:5px;border-radius:50%;background:var(--uip-danger)"></b>`:''}</span>`).join('')}</div>`));
D['bottomnav.notch']=t=>P(page+`<svg style="position:absolute;left:0;bottom:0;width:100%;height:28px" viewBox="0 0 96 28" preserveAspectRatio="none"><path d="M0 4 H34 C38 4 38 16 48 16 C58 16 58 4 62 4 H96 V28 H0 Z" fill="var(--uip-surface)" stroke="var(--uip-b)" stroke-width=".5"/></svg>`+ab('♡',`left:50%;bottom:16px;transform:translateX(-50%);width:20px;height:20px;border-radius:50%;background:${A};color:#fff;font-size:10px;text-align:center;line-height:20px`)+ab(`<span style="color:${M}">⌂</span><span style="color:${M}">⊞</span><span style="width:16px"></span><span style="color:${M}">✉</span><span style="color:${M}">◯</span>`,`left:0;right:0;bottom:4px;display:flex;justify-content:space-around;font-size:10px`));
D['bottomnav.dot']=t=>P(page+bnav(icons4()+`<div style="position:absolute;bottom:3px;width:4px;height:4px;margin-left:-2px;border-radius:50%;background:${A};${an('u6ind',4)};transform:translateX(10px)"></div>`));

/* ---------- sliders ---------- */
const track=(x,ex='')=>`<div style="position:relative;width:110px;height:4px;border-radius:2px;background:${BS};${ex}">${x}</div>`;
const thumb=(ex='')=>`<span style="position:absolute;top:50%;width:14px;height:14px;margin:-7px 0 0 -7px;border-radius:50%;background:#fff;border:2px solid ${A};box-shadow:0 1px 3px rgba(0,0,0,.2);${ex}"></span>`;
D['slider.range']=t=>col(`<div style="display:flex;align-items:flex-end;gap:2px;height:28px;width:110px">${[3,5,8,12,18,22,17,13,9,6,4,3].map((h,i)=>`<span style="flex:1;height:${h}px;border-radius:1px;background:${i>2&&i<9?A:BS}"></span>`).join('')}</div>`+track(`<div style="position:absolute;left:25%;right:25%;height:100%;background:${A}"></div>`+thumb('left:25%')+thumb('left:75%'))+`<div style="display:flex;justify-content:space-between;width:110px;font-size:10px;color:${SUB}"><span>₩60k</span><span>₩196k</span></div>`,'auto',8);
D['slider.steps']=t=>col(`<div style="font-size:20px;font-weight:600;text-align:center;width:110px">L</div>`+track(`<div style="position:absolute;left:0;width:75%;height:100%;background:${A}"></div>`+[0,25,50,75,100].map(p=>`<span style="position:absolute;left:${p}%;top:50%;width:6px;height:6px;margin:-3px;border-radius:50%;background:${p<=75?A:BS}"></span>`).join('')+thumb('left:75%'))+`<div style="display:flex;justify-content:space-between;width:116px;font-size:9px;color:${SUB}">${['XS','S','M','L','XL'].map(x=>`<span>${x}</span>`).join('')}</div>`,'auto',8);
D['slider.bubble']=t=>`<div style="padding-top:24px">`+track(`<div style="position:absolute;left:0;height:100%;background:${A};${an('u6fw',3)}"></div>`+`<span style="position:absolute;top:50%;${an('u6bub',3)}"><span style="position:absolute;bottom:12px;left:-14px;width:28px;font-size:9px;text-align:center;background:${A};color:#fff;border-radius:5px;padding:2px 0">68%</span>${thumb('left:0')}</span>`)+`</div>`;
D['slider.vertical']=t=>rowf([['☀','60%'],['🔊','85%']].map(([i,v],k)=>`<div style="display:flex;flex-direction:column;align-items:center;gap:4px"><div style="position:relative;width:26px;height:74px;border-radius:9px;background:${BS};overflow:hidden"><div style="position:absolute;left:0;right:0;bottom:0;background:${A};${an('u6fh',3)};animation-delay:${k*.6}s"></div><span style="position:absolute;bottom:4px;left:0;right:0;text-align:center;font-size:10px">${i}</span></div><span style="font-size:9px;color:${SUB}">${v}</span></div>`).join(''),14);
D['slider.emoji']=t=>col(`<div style="font-size:30px;text-align:center;width:110px;animation:u6aur 3s infinite">🙂</div>`+track(`<div style="position:absolute;left:0;width:70%;height:100%;background:#f5b400"></div>`+thumb('left:70%;border-color:#f5b400'))+`<div style="font-size:10px;color:${SUB};text-align:center;width:110px">${t('좋았어요!','Loved it!')}</div>`,'auto',8);
D['slider.color']=t=>col(`<div style="width:110px;height:34px;border-radius:8px;background:#e7559b"></div>`+`<div style="position:relative;width:110px;height:8px;border-radius:4px;background:linear-gradient(90deg,red,#ff0,lime,cyan,blue,#f0f,red)">${thumb('left:88%;border-color:#fff;background:#e7559b')}</div>`+rowf(['#f3a7c9','#e7559b','#c2185b','#880e4f'].map(c=>`<span style="width:18px;height:14px;border-radius:4px;background:${c}"></span>`).join(''),6),'auto',9);
D['slider.knob']=t=>`<div style="position:relative;width:76px;height:76px"><svg width="76" height="76" viewBox="0 0 76 76"><circle cx="38" cy="38" r="30" fill="none" stroke="var(--uip-bs)" stroke-width="5" stroke-dasharray="141 200" transform="rotate(135 38 38)" stroke-linecap="round"/><circle cx="38" cy="38" r="30" fill="none" stroke="var(--uip-ac)" stroke-width="5" stroke-dasharray="100 200" transform="rotate(135 38 38)" stroke-linecap="round"/></svg><div style="position:absolute;inset:14px;border-radius:50%;background:${S};box-shadow:0 2px 6px rgba(0,0,0,.15);${an('u6rot',4)}"><span style="position:absolute;top:4px;left:50%;width:3px;height:9px;margin-left:-1.5px;border-radius:2px;background:${A}"></span></div><div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:600;pointer-events:none">22.5°</div></div>`;
D['slider.scrubber']=t=>col(`<div style="width:120px;height:46px;border-radius:8px;background:linear-gradient(135deg,#3b5bdb,#1c2a6b);display:flex;align-items:center;justify-content:center;color:#fff">▶</div>`+`<div style="position:relative;width:120px;height:3px;background:${BS};border-radius:2px"><div style="position:absolute;left:0;height:100%;width:60%;background:${M}"></div><div style="position:absolute;left:0;height:100%;background:${A};${an('u6fw',5,'linear')}"></div></div><div style="display:flex;justify-content:space-between;width:120px;font-size:9px;color:${SUB}"><span>2:48</span><span>-1:12</span></div>`,'auto',6);

/* ---------- toggles ---------- */
const tg=(knob,trackEx='',lab='')=>`<div style="display:flex;flex-direction:column;align-items:center;gap:6px"><div style="position:relative;width:44px;height:24px;border-radius:12px;padding:3px;box-sizing:border-box;${trackEx}">${knob}</div>${lab}</div>`;
const kb=(ex='')=>`<span style="display:block;width:18px;height:18px;border-radius:9px;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.25);${ex}"></span>`;
D['toggle.classic']=t=>tg(kb(an('u6tg',3)),an('u6bg',3));
D['toggle.squishy']=t=>tg(kb(an('u6sq',3)),an('u6bg',3));
D['toggle.daynight']=t=>tg(`<span style="display:block;width:18px;height:18px;border-radius:50%;background:#ffd84d;box-shadow:inset -5px -2px 0 0 rgba(0,0,0,.0);${an('u6tg',3)}"></span>`+`<span style="position:absolute;right:7px;top:4px;font-size:8px;color:#fff">✦</span>`,an('u6dn',3));
D['toggle.check']=t=>tg(`<span style="display:flex;align-items:center;justify-content:center;width:18px;height:18px;border-radius:9px;background:#fff;font-size:11px;color:${A};box-shadow:0 1px 3px rgba(0,0,0,.25);${an('u6tg',3)}">✓</span>`,an('u6bg',3));
D['toggle.label']=t=>tg(kb(an('u6tg',3)+';position:relative;z-index:1')+`<span style="position:absolute;left:6px;top:6px;font-size:8px;font-weight:600;color:#fff">ON</span><span style="position:absolute;right:5px;top:6px;font-size:8px;font-weight:600;color:${SUB}">OFF</span>`,`width:52px;${an('u6bg',3)}`.replace('44px','52px'));
D['toggle.liquid']=t=>tg(`<span style="position:absolute;left:0;top:0;bottom:0;border-radius:12px;background:linear-gradient(90deg,${A},#7ab8ff);${an('u6liq',3)}"></span>`+kb(an('u6tg',3)+';position:relative'),`background:${BS};overflow:hidden`);
D['toggle.rocker']=t=>`<div style="perspective:200px"><div style="display:flex;width:56px;height:30px;border-radius:6px;background:#2a2f3a;box-shadow:inset 0 2px 4px rgba(0,0,0,.5);overflow:hidden;${an('u6rk',3)};transform-style:preserve-3d"><span style="flex:1;display:flex;align-items:center;justify-content:center;color:#ddd;font-size:12px">O</span><span style="flex:1;display:flex;align-items:center;justify-content:center;color:#ddd;font-size:12px;border-left:1px solid #444">I</span></div></div>`;
D['toggle.neon']=t=>`<div style="background:#0d1220;padding:14px;border-radius:10px">`+tg(`<span style="display:block;width:18px;height:18px;border-radius:9px;background:#39f;box-shadow:0 0 8px #39f;${an('u6tg',3)}"></span>`,`border:1.5px solid;background:#0d1220;${an('u6glow',3)}`)+`</div>`;

/* ---------- button trends ---------- */
const bx=(label,ex,wrap='')=>`<div style="display:flex;align-items:center;justify-content:center;width:100%;height:100%;${wrap}"><button style="font:inherit;font-size:12px;padding:8px 16px;cursor:pointer;${ex}" onmousedown="this.style.transform='scale(.95)'" onmouseup="this.style.transform=''" onmouseleave="this.style.transform=''">${label}</button></div>`;
D['btnstyle.glass']=t=>bx(t('시작하기','Get started'),'color:#fff;border-radius:12px;background:rgba(255,255,255,.22);border:1px solid rgba(255,255,255,.55);backdrop-filter:blur(8px);transition:.15s','background:radial-gradient(circle at 30% 40%,#7ea6ff,transparent 55%),radial-gradient(circle at 75% 70%,#c49bff,transparent 55%),#1b2340');
D['btnstyle.liquid']=t=>bx(t('계속','Continue'),'color:#fff;border-radius:999px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.5);box-shadow:inset 0 1px 1px rgba(255,255,255,.7),inset 0 -6px 12px rgba(255,255,255,.12),0 6px 16px rgba(0,0,0,.25);backdrop-filter:blur(3px) saturate(1.6);transition:.15s','background:repeating-linear-gradient(90deg,#1b2340 0 14px,#4f6fdc 14px 20px)');
D['btnstyle.neu']=t=>bx(t('재생','Play'),`color:#7a8699;border:0;border-radius:12px;background:#e6eaf0;box-shadow:5px 5px 10px #c3c8d0,-5px -5px 10px #fff;transition:.15s`,'background:#e6eaf0');
D['btnstyle.brutal']=t=>bx(t('지금 구매','BUY NOW'),'color:#000;font-weight:700;border:2px solid #000;border-radius:4px;background:#ffd84d;box-shadow:4px 4px 0 #000;transition:.1s','background:#fff');
D['btnstyle.aurora']=t=>bx(t('생성하기','Generate'),'color:#fff;border-radius:10px;border:1px solid rgba(255,255,255,.25);background:#0f1426;box-shadow:0 0 18px rgba(130,90,255,.6),0 0 30px rgba(0,200,255,.35);transition:.15s','background:#0a0e1c');
D['btnstyle.clay']=t=>bx(t('참여','Join'),'color:#4a3b6b;border:0;border-radius:18px;background:#d9ccff;box-shadow:inset -4px -4px 8px rgba(0,0,0,.12),inset 4px 4px 8px rgba(255,255,255,.7),6px 8px 14px rgba(120,90,200,.3);transition:.15s','background:#f3eefe');
D['btnstyle.tactile']=t=>`<div style="display:flex;align-items:center;justify-content:center;width:100%;height:100%"><button style="font:inherit;font-size:12px;padding:8px 18px;color:#fff;border:0;border-radius:10px;background:${A};box-shadow:0 5px 0 #1c45b8;transform:translateY(0);transition:.08s;cursor:pointer" onmousedown="this.style.transform='translateY(4px)';this.style.boxShadow='0 1px 0 #1c45b8'" onmouseup="this.style.transform='';this.style.boxShadow='0 5px 0 #1c45b8'" onmouseleave="this.style.transform='';this.style.boxShadow='0 5px 0 #1c45b8'">${t('시작','Start')}</button></div>`;
D['btnstyle.morph']=t=>`<div style="display:flex;align-items:center;justify-content:center;width:100%;height:100%"><button onclick="const b=this;if(b.dataset.s)return;b.dataset.s=1;b.style.width='34px';b.innerHTML='<span class=\\'uip-spin\\' style=\\'width:14px;height:14px;border-color:rgba(255,255,255,.4);border-top-color:#fff\\'></span>';setTimeout(()=>{b.innerHTML='✓';b.style.background='#16a34a'},1100);setTimeout(()=>{b.style.width='96px';b.innerHTML=b.dataset.l;b.style.background='';delete b.dataset.s},2400)" data-l="${t('보내기','Send')}" style="font:inherit;font-size:12px;width:96px;height:34px;color:#fff;border:0;border-radius:17px;background:${A};transition:.3s;cursor:pointer;display:flex;align-items:center;justify-content:center">${t('보내기','Send')}</button></div>`;

/* ---------- progress steps ---------- */
D['steps.stepper']=t=>col(rowf([['✓',1],['2',1],['3',0],['4',0]].map(([x,on],i)=>`${i?`<span style="width:12px;height:1.5px;background:${i<2?A:BS}"></span>`:''}<span style="width:20px;height:20px;border-radius:50%;font-size:10px;display:flex;align-items:center;justify-content:center;${i==0?`background:${A};color:#fff`:i==1?`border:1.5px solid ${A};color:${A}`:`border:1.5px solid ${BS};color:${M}`}">${x}</span>`).join(''),0)+`<div style="display:flex;justify-content:space-between;width:128px;font-size:9px;color:${SUB}">${[t('장바구니','Cart'),t('정보','Info'),t('결제','Pay'),t('완료','Done')].map(x=>`<span>${x}</span>`).join('')}</div>`,'auto',5);
D['steps.timeline']=t=>`<div style="font-size:10px">${[t('주문 완료','Ordered'),t('배송 시작','Shipped'),t('배송 중','Out for delivery'),t('도착','Delivered')].map((x,i)=>`<div style="display:flex;gap:7px;align-items:flex-start;position:relative;padding-bottom:7px">${i<3?`<span style="position:absolute;left:5.5px;top:12px;bottom:0;width:1.5px;background:${i<2?A:BS}"></span>`:''}<span style="width:12px;height:12px;border-radius:50%;flex:none;font-size:7px;color:#fff;display:flex;align-items:center;justify-content:center;background:${i<3?A:BS}">${i<3?'✓':''}</span><span style="color:${i<3?'inherit':M}">${x}</span></div>`).join('')}</div>`;
D['steps.segments']=t=>col(`<div style="display:flex;gap:4px;width:120px">${[0,1,2,3].map(i=>`<span style="flex:1;height:4px;border-radius:2px;background:${i<3?A:BS}"></span>`).join('')}</div><div style="font-size:22px;font-weight:600;margin-top:6px">03</div><div style="font-size:10px;color:${SUB}">${t('관심사 고르기','Pick interests')}</div>`,'auto',2);
D['steps.dots']=t=>col(`<div style="width:120px;overflow:hidden"><div style="display:flex;width:300%;${an('u6car',6)}">${['✦','◎','☾'].map(x=>`<div style="width:33.33%;height:50px;border-radius:10px;background:var(--uip-acbg);display:flex;align-items:center;justify-content:center;font-size:20px;color:${A}">${x}</div>`).join('')}</div></div>`+rowf([0,1,2].map(i=>`<span style="height:5px;border-radius:3px;background:${i==1?A:BS};width:${i==1?14:5}px"></span>`).join(''),4,'justify-content:center'),'auto',8);
D['steps.ring']=t=>col(`<svg width="62" height="62" viewBox="0 0 62 62"><circle cx="31" cy="31" r="14" fill="none" stroke="var(--uip-bs)" stroke-width="4"/><circle cx="31" cy="31" r="14" fill="none" stroke="var(--uip-ac)" stroke-width="4" stroke-dasharray="88" stroke-linecap="round" transform="rotate(-90 31 31)" style="${an('u6ring',3)}"/><text x="31" y="35" text-anchor="middle" font-size="11" fill="var(--uip-ac)">✓</text></svg><div style="font-size:10px;color:${SUB}">${t('프로필 완성','Profile complete')}</div>`,'auto',2);
D['steps.chevron']=t=>`<div style="display:flex;font-size:10px">${[t('장바구니','Cart'),t('배송','Ship'),t('결제','Pay')].map((x,i)=>`<span style="padding:5px 12px 5px ${i?16:10}px;margin-left:${i?-6:0}px;background:${i==0?A:BS};color:${i==0?'#fff':SUB};clip-path:polygon(0 0,calc(100% - 8px) 0,100% 50%,calc(100% - 8px) 100%,0 100%${i?',8px 50%':''})">${x}</span>`).join('')}</div>`;
D['steps.counter']=t=>col(`<div style="font-size:11px;color:${SUB};width:120px">${t('설문','Survey')} <b style="color:${A}">3</b> / 4</div><div style="width:120px;height:4px;border-radius:2px;background:${BS};overflow:hidden"><div style="height:100%;width:75%;background:${A}"></div></div><div style="font-size:11px;width:120px;margin-top:4px">${t('자주 쓰는 기능은?','Which do you use most?')}</div>`,'auto',5);
D['steps.checklist']=t=>col(`<div style="font-size:10px;width:120px;display:flex;justify-content:space-between"><b>${t('설정','Setup')} 2/4</b><span style="color:${A}">50%</span></div><div style="height:3px;width:120px;background:${BS};border-radius:2px"><div style="height:100%;width:50%;background:${A}"></div></div>`+[t('계정 만들기','Create account'),t('사진 추가','Add a photo'),t('친구 초대','Invite a friend'),t('알림 켜기','Turn on alerts')].map((x,i)=>`<label style="display:flex;gap:5px;align-items:center;font-size:10px;width:120px;cursor:pointer;${i<2?'color:'+M+';text-decoration:line-through':''}"><input type="checkbox" ${i<2?'checked':''} onchange="this.parentNode.style.textDecoration=this.checked?'line-through':'';this.parentNode.style.color=this.checked?'${M}':''" style="margin:0;accent-color:${A}">${x}</label>`).join(''),'auto',4);

/* ---------- refresh ---------- */
const feed=(n=4,newN=0,ex='')=>Array.from({length:n},(_,i)=>`<div style="display:flex;gap:5px;align-items:center;padding:4px 6px;${i<newN?'background:var(--uip-acbg);':''}${ex}"><span style="width:12px;height:12px;border-radius:50%;background:${i<newN?A:BS};flex:none"></span>${ln(i%2?'55%':'70%')}</div>`).join('');
D['refresh.pull']=t=>P(ab(sp(14),`left:50%;top:6px;margin-left:-7px`)+`<div style="background:${S};position:relative;${an('u6pull',3)}">${feed(5,1)}</div>`);
D['refresh.elastic']=t=>P(ab(`<span style="display:block;width:8px;height:8px;border-radius:50%;background:${A}"></span>`,`left:50%;top:12px;margin-left:-4px`)+`<div style="background:${S};position:relative;transform-origin:top;${an('u6el',2.6,'cubic-bezier(.3,1.4,.6,1)')}">${feed(5)}</div>`);
D['refresh.release']=t=>P(ab(`<span style="font-size:9px;color:${A}">↓ ${t('놓으면 새로고침','Release to refresh')}</span>`,`left:0;right:0;top:6px;text-align:center`)+`<div style="background:${S};position:relative;${an('u6pull',3)}">${feed(5)}</div>`);
D['refresh.newposts']=t=>P(feed(6)+ab(`↑ ${t('새 글 3개','3 new posts')}`,`left:50%;top:6px;font-size:9px;white-space:nowrap;padding:3px 8px;border-radius:999px;background:${A};color:#fff;box-shadow:0 2px 6px rgba(0,0,0,.2);${an('u6pill',3.5)}`));
